"""Discounted prices for the example catalog."""

from __future__ import annotations


def discounted(price: float, percent: float) -> float:
    """Apply a percentage discount.

    Discounts must be between zero and one hundred percent.
    """
    if not 0 <= percent <= 100:
        raise ValueError("a discount must be between 0 and 100 percent")
    price = price * (1 - percent / 100)
    return round(price, 2)
